1: <script setup lang="ts">
2: import { ref, reactive, computed, onMounted, onUnmounted } from 'vue'
3: import { onLoad } from '@dcloudio/uni-app'
4: import WatermarkCamera from '../../../components/WatermarkCamera.vue'
5: import { useEvaluationStore } from '../../../stores/evaluation'
6: import { useBack } from '../../../composables/useBack'
7: import { toastError } from '../../../utils/notify'
8: import { uploadFile, resolveAssetUrl } from '../../../utils/upload'
9: import type { Photo } from '../../../stores/photos'
10: import {
11:   checkTypeTitles, isCheckType, isStreetAndAbove, evalLevelOptions,
12:   type CheckType, type CheckForm, type CheckItem, type CategoryGroup, type ProjectGroup, type SaveCheckPayload, type SaveCheckItem, type ScoreOption,
13: } from '../../../types/evaluation'
14: 
15: const store = useEvaluationStore()
16: const checkType = ref<CheckType>('1')
17: const checkRecordId = ref('')
18: const form = ref<CheckForm | null>(null)
19: const step = ref(0)                 // 0..4 五类；5 整体情况
20: const error = ref('')
21: const message = ref('')
22: const busy = ref(false)
23: const loading = ref(false)
24: const photoMap = reactive<Record<string, Photo[]>>({})
25: const attachments = ref<Photo[]>([])
26: 
27: const { back } = useBack('/pages/project-check/records/index')
28: const title = computed(() => checkTypeTitles[checkType.value])
29: const totalSteps = computed(() => (form.value?.totalCount ?? 5))
30: const isOverall = computed(() => step.value >= totalSteps.value)
31: const currentCategory = computed<CategoryGroup | null>(() => form.value && step.value < totalSteps.value ? form.value.categoryList[step.value] : null)
32: const showFreq = computed(() => isStreetAndAbove(checkType.value))
33: /* 是否存在需要整改的项（扣分项：非不涉及且得分低于满分）；满分时无需整改，不显示整改通知书相关选项 */
34: const hasRectifyItems = computed(() => {
35:   const f = form.value
36:   if (!f) return false
37:   for (const cat of f.categoryList) for (const proj of cat.projectList) for (const it of proj.itemList) {
38:     if (it.isNotApplicable !== '1' && it.itemScore != null && it.itemScore !== '' && Number(it.itemScore) < topScore(it)) return true
39:   }
40:   return false
41: })
42: 
43: /* ===== 打分档位判定 ===== */
44: function isNAOption(o: { optionName: string }) { return o.optionName.includes('不涉及') }
45: /** 选中高亮：不涉及项看 isNotApplicable 标志，其余项看分值相等（不依赖选项名是否含分值，兼容真实接口纯文字选项名） */
46: function isChosen(item: CheckItem, o: ScoreOption) {
47:   if (isNAOption(o)) return item.isNotApplicable === '1'
48:   return item.isNotApplicable !== '1' && item.itemScore != null && item.itemScore !== '' && String(o.score) === String(item.itemScore)
49: }
50: function topScore(item: CheckItem) {
51:   const scores = item.optionList.filter(o => !isNAOption(o)).map(o => Number(o.score))
52:   return scores.length ? Math.max(...scores) : 0
53: }
54: function isTopOrNA(item: CheckItem) {
55:   if (item.isNotApplicable === '1') return true
56:   return item.itemScore != null && item.itemScore !== '' && Number(item.itemScore) === topScore(item)
57: }
58: function pickOption(item: CheckItem, o: { optionName: string; score: number | string }) {
59:   if (isNAOption(o)) { item.isNotApplicable = '1'; item.itemScore = 0 }
60:   else { item.isNotApplicable = '0'; item.itemScore = o.score }
61:   recalc()
62: }
63: /** 接口 optionList 常不返回“不涉及”（靠 isNotApplicable 标志单独表示），缺失时前端补一行 */
64: function hasNAOption(item: CheckItem) { return item.optionList.some(o => isNAOption(o)) }
65: function pickNA(item: CheckItem) { item.isNotApplicable = '1'; item.itemScore = 0; recalc() }
66: function answered(item: CheckItem) { return item.isNotApplicable === '1' || (item.itemScore != null && item.itemScore !== '') }
67: function projAnswered(proj: ProjectGroup) { return proj.itemList.filter(answered).length }
68: function recalc() {
69:   const f = form.value
70:   if (!f) return
71:   let finished = 0
72:   let actual = 0
73:   for (const cat of f.categoryList) {
74:     let checked = 0; let catScore = 0
75:     for (const proj of cat.projectList) {
76:       let projScore = 0
77:       for (const it of proj.itemList) {
78:         if (it.isNotApplicable === '1') { checked++; continue }
79:         if (it.itemScore != null && it.itemScore !== '') { projScore += Number(it.itemScore); checked++ }
80:       }
81:       proj.actualScore = projScore
82:       catScore += projScore
83:     }
84:     cat.actualScore = catScore
85:     cat.checkedCount = checked
86:     cat.finished = cat.itemCount > 0 && checked >= cat.itemCount
87:     if (cat.finished) finished++
88:     actual += catScore
89:   }
90:   f.actualScore = Number(actual.toFixed(1))
91:   f.finishedCount = finished
92:   f.progressPercent = Math.round((finished / (f.totalCount || 5)) * 100)
93: }
94: 
95: /* ===== 图片 ===== */
96: function initPhotos(item: CheckItem) {
97:   if (photoMap[item.checkItemId]) return
98:   photoMap[item.checkItemId] = (item.images ? item.images.split(',').filter(Boolean) : []).map((url, i) => ({ id: `${item.checkItemId}-${i}`, source: url, url, status: 'done' as const }))
99: }
100: function photosOf(item: CheckItem) { initPhotos(item); return photoMap[item.checkItemId] }
101: function setPhotos(item: CheckItem, list: Photo[]) {
102:   photoMap[item.checkItemId] = list
103:   item.images = list.filter(p => p.status === 'done' && p.url).map(p => p.url).join(',')
104: }
105: 
106: /* ===== 加载 ===== */
