tool_input.content:
function parseFillOptions(raw) {
  if (raw == null) return undefined
  const text = String(raw).trim()
  if (!text) return undefined
  if (text.startsWith('[')) {
    try {
      const parsed = JSON.parse(text)
      if (Array.isArray(parsed)) {
        const arr = parsed.map(v => String(v).trim()).filter(Boolean)
        if (arr.length) return arr
      }
    } catch { /* fallthrough */ }
  }
  const arr = text
    .replace(/^[\[（(]+|[\]）)]+$/g, '')
    .split(/[,，]/)
    .map(v => v.trim().replace(/^["'\s]+|["'\s]+$/g, ''))
    .filter(Boolean)
  return arr.length ? arr : undefined
}
const tests = ['["有","无"]', '["是","否"]', '有,无', '["有", "无"]', '是，否', '', null]
for (const t of tests) console.log(JSON.stringify(t), '->', JSON.stringify(parseFillOptions(t)))
